// ------------------------------------------------------------------ helpers

function hexToVec(hex) {
  const n = parseInt(hex.slice(1), 16);
  return C(((n >> 16) & 255) / 255, ((n >> 8) & 255) / 255, (n & 255) / 255);
}

const FILL = {
  Solid: mod.UIBgFill.Solid, Blur: mod.UIBgFill.Blur,
  OutlineThin: mod.UIBgFill.OutlineThin, OutlineThick: mod.UIBgFill.OutlineThick,
  None: mod.UIBgFill.None,
};
const ANCHOR = {
  Left: mod.UIAnchor.CenterLeft, CenterLeft: mod.UIAnchor.CenterLeft,
  Right: mod.UIAnchor.CenterRight, CenterRight: mod.UIAnchor.CenterRight,
  TopLeft: mod.UIAnchor.TopLeft, TopRight: mod.UIAnchor.TopRight,
  Center: mod.UIAnchor.Center, TopCenter: mod.UIAnchor.TopCenter,
};

function fmtWindow(ms) {
  const total = Math.max(0, Math.round(ms / 1000));
  const s = total % 60, m = Math.floor(total / 60);
  const ss = s < 10 ? "0" + s : String(s);
  return m > 0 ? m + ":" + ss : "0:" + ss;
}
function trunc(s, max) { return s.length <= max ? s : s.slice(0, max - 1) + "\u2026"; }

function resolveToken(tok, fields) {
  const body = tok.slice(2, tok.length - 2);
  const dot = body.indexOf(".");
  if (dot < 0) return body;
  const g = fields[body.slice(0, dot)];
  if (g === undefined) return body;
  const v = g[body.slice(dot + 1)];
  return v === undefined ? body : String(v);
}

function prop(n, key, fields, scope) {
  if (n.bind && n.bind[key] !== undefined) {
    const s = fields[scope];
    if (s !== undefined && s[n.bind[key]] !== undefined) return String(s[n.bind[key]]);
  }
  const raw = n[key];
  if (raw === undefined) return undefined;
  return typeof raw === "string" && raw.startsWith("{{") ? resolveToken(raw, fields) : String(raw);
}

// ------------------------------------------------------------ catalog model

// Mirrors src/ui.ts: one unified Row type across both tabs.
const ROWS = {
  sfx: CATALOG.sfx.entries.map((e) => ({ type: "sfx", entry: e })),
  vfx: [
    ...CATALOG.vfx.entries.map((e) => ({ type: "spawn", entry: e })),
    ...SCREEN_FX.map((f) => ({ type: "screen", id: f.id, display: f.display, category: f.category })),
  ],
};
// Screen-effect categories (Gas, Screen) go first, mirroring registerGroups() in src/ui.ts.
const VFX_GROUPS = [...SCREEN_FX.map((f) => f.category).filter((c2, i, a) => a.indexOf(c2) === i), ...CATALOG.vfx.categories];
const GROUPS = { sfx: CATALOG.sfx.categories, vfx: VFX_GROUPS.filter((c2, i, a) => a.indexOf(c2) === i) };

const rowKey = (r) => (r.type === "screen" ? "screen:" + r.id : r.entry.name);
const rowDisplay = (r) => (r.type === "screen" ? r.display : r.entry.display);
const rowCategory = (r) => (r.type === "screen" ? r.category : r.entry.category);

function listFor(tab, group, f) {
  const q = (f.query || "").trim().toLowerCase();
  const name = q === "" ? (group === 0 ? "*" : (GROUPS[tab][group - 1] ?? "")) : "*";
  return ROWS[tab].filter((r) => {
    if (name !== "*" && rowCategory(r) !== name) return false;
    if (tab === "sfx") {
      if (f.dim && r.entry.dim !== f.dim) return false;
      if (f.kind && r.entry.kind !== f.kind) return false;
    } else {
      if (f.vfx === "world" && r.type !== "spawn") return false;
      if (f.vfx === "screen" && r.type !== "screen") return false;
    }
    if (q === "") return true;
    return rowDisplay(r).toLowerCase().includes(q) || rowKey(r).toLowerCase().includes(q);
  });
}
function groupIndex(tab, name) {
  const i = GROUPS[tab].indexOf(name);
  return i < 0 ? 0 : i + 1;
}
const perPage = SCENE.grid.rows;
const pageCount = (n) => Math.max(1, Math.ceil(n / perPage));

