const view = new URLSearchParams(location.search).get("view") || VIEW;

function pick() {
  const base = { tab: "sfx", group: 0, page: 0, selected: "", armed: "", scale: 1.0, amp: "0.80", rng: "40", open: true, spawned: 0, searchOpen: false, kbPage: 0, query: "", dim: "", kind: "", vfx: "", sel: 0 };
  switch (view) {
    case "vfx": return { ...base, tab: "vfx" };
    case "snow": return { ...base, tab: "vfx", group: groupIndex("vfx", "Snow") };
    case "gas": return { ...base, tab: "vfx", group: groupIndex("vfx", "Gas") };
    case "grouped": return { ...base, tab: "sfx", group: groupIndex("sfx", "Soldier_Melee") };
    case "selected": return { ...base, tab: "vfx", scale: 1.8, selected: rowKey(listFor("vfx", 0, { query: "", dim: "", kind: "", vfx: "" })[3]) };
    case "armed": return { ...base, tab: "vfx", open: false, scale: 2.4, spawned: 7, armed: rowKey(listFor("vfx", 0, { query: "", dim: "", kind: "", vfx: "" })[3]), selected: rowKey(listFor("vfx", 0, { query: "", dim: "", kind: "", vfx: "" })[3]) };
    case "closed": return { ...base, open: false, armed: rowKey(ROWS.sfx[0]), spawned: 0 };
    case "empty": return { ...base, tab: "vfx", group: GROUPS.vfx.length - 1 };
    case "search": return { ...base, tab: "sfx", searchOpen: true, query: "explos" };
      case "pfxSfx": return { ...base, tab: "sfx", searchOpen: true, kbPage: 1 };
      case "pfxVfx": return { ...base, tab: "vfx", searchOpen: true, kbPage: 1 };
    case "filters": return { ...base, tab: "sfx", dim: "3d", kind: "loop" };
    case "music": return { ...base, tab: "music" };
    case "radio": return { ...base, tab: "radio" };
    default: return base;
  }
}

