function rowFields(r) {
  const key = rowKey(r);
  const selected = key === V.selected;
  const armed = key === V.armed;
  const selLabel = armed ? "ARMED" : "SELECT";
  const selColor = armed ? "#FFFFFF" : P.ink;
  const selBg = armed ? P.green : selected ? P.rowSel : P.row;
  const head = {
    bg: selected ? P.rowSel : P.row,
    name: rowDisplay(r),
    nameColor: selected ? P.ink : P.inkDim,
    category: rowCategory(r),
    selLabel, selColor, selBg,
  };

  if (r.type === "sfx") {
    const e = r.entry;
    const is3d = e.dim === "3d";
    const isLoop = e.kind === "loop";
    const b1c = is3d ? P.blue : P.amber;
    const b2c = isLoop ? P.green : P.grey;
    return { ...head, actGlyph: "P", actColor: "#FFFFFF", actBg: b1c, b1: is3d ? "3D" : "2D", b1Color: b1c, b1Bg: b1c, b2: isLoop ? "LOOP" : "ONE", b2Color: b2c, b2Bg: b2c };
  }
  const world = r.type === "spawn";
  const b1c = world ? P.violet : P.green;
  const b2c = world ? P.blue : P.amber;
  return { ...head, actGlyph: world ? "S" : "T", actColor: "#FFFFFF", actBg: b1c, b1: world ? V.scale.toFixed(2) + "x" : "PLAYER", b1Color: b1c, b1Bg: b1c, b2: world ? "WORLD" : "EFFECT", b2Color: b2c, b2Bg: b2c };
}

// ------------------------------------------------------------------- render

const BASE = { anchor: mod.UIAnchor.TopLeft, visible: true, parent: null, depth: mod.UIDepth.AboveGameUI, receiver: {} };

function add(n, ox, oy, fields, scope) {
  let w = n.w ?? 0;
  if (n.wScale !== undefined) w = w * Number(prop(n, n.wScale, fields, scope) ?? 0);

  const common = {
    ...BASE,
    position: { x: ox + n.x, y: oy + n.y },
    size: { width: Math.max(0, w), height: n.h ?? 0 },
    bgColor: hexToVec(prop(n, "bg", fields, scope) ?? "#000000"),
    bgAlpha: Number(prop(n, "bgAlpha", fields, scope) ?? 1),
    bgFill: FILL[prop(n, "fill", fields, scope)] ?? mod.UIBgFill.None,
  };

  if (n.k === "container") return new UIContainer(common);

  const tSize = Number(prop(n, "textSize", fields, scope) ?? 7);
  const tColor = hexToVec(prop(n, n.k === "text" ? "color" : "textColor", fields, scope) ?? "#FFFFFF");
  const tAnchor = ANCHOR[prop(n, "align", fields, scope)] ?? mod.UIAnchor.Center;

  if (n.k === "text") {
    return new UIText({ ...common, message: prop(n, "text", fields, scope) ?? "", textSize: tSize, textColor: tColor, textAlpha: Number(prop(n, "textAlpha", fields, scope) ?? 1), textAnchor: tAnchor, wrap: n.wrap === true });
  }
  const isText = n.k === "textbutton";
  return new (isText ? UITextButton : UIButton)({
    ...common,
    message: isText ? prop(n, "text", fields, scope) ?? "" : "",
    textSize: tSize, textColor: tColor, textAnchor: tAnchor,
    baseColor: hexToVec(prop(n, "bg", fields, scope) ?? "#000000"),
    baseAlpha: Number(prop(n, "bgAlpha", fields, scope) ?? 1),
    enabled: n.enabled !== false,
  });
}

function walk(nodes, ox, oy, fields, scope) {
  const groupVisible = {};
  // A group may carry its own origin; children are relative to it.
  const groupOrigin = {};
  for (let i = 0; i < nodes.length; i++) {
    const n = nodes[i];
    if (n.k === "group") {
      // A group nested inside a hidden group is itself hidden. buildNodes() in
      // ui.ts gets this from recursion; walk() is flat, so it has to check.
      const id = n.id ?? "g" + i;
      if (n.parent !== undefined && groupVisible[n.parent] === false) {
        groupVisible[id] = false;
        groupOrigin[id] = { x: 0, y: 0 };
        continue;
      }
      const bound = prop(n, "visible", fields, scope);
      groupVisible[id] = bound !== undefined ? bound !== "0" : n.visible !== false;
      groupOrigin[id] = { x: n.x, y: n.y };
      continue;
    }
    let gx = 0, gy = 0;
    if (n.parent !== undefined) {
      if (groupVisible[n.parent] === false) continue;
      const o = groupOrigin[n.parent];
      if (o) { gx = o.x; gy = o.y; }
    }

    if (n.k === "repeat") {
      const tpl = n.template;
      if (!tpl) continue;
      const count = n.count ?? 0, cols = n.cols ?? 0, gap = n.gap ?? 0;
      const gapX = n.gapX ?? gap, gapY = n.gapY ?? gap;
      const tw = tpl.w ?? 0, th = tpl.h ?? 0;
      for (let j = 0; j < count; j++) {
        const cx = cols > 0 ? (j % cols) * (tw + gapX) : j * (tw + gap);
        const cy = cols > 0 ? Math.floor(j / cols) * (th + gapY) : 0;
        add({ ...tpl, x: tpl.x + cx, y: tpl.y + cy }, ox + gx + n.x, oy + gy + n.y, fields, scope);
      }
      continue;
    }
    add(n, ox + gx, oy + gy, fields, scope);
  }
}

const GF = { sh: P, f: chromeFields };
walk(SCENE.screen, 0, 0, GF, "f");
if (V.open && !TESTER) {
// rail: ALL is a static text row, the groups are buttons below it
const NOF = { query: "", dim: "", kind: "", vfx: "" };
const counts = [listFor(V.tab, 0, NOF).length];
for (let i = 0; i < GROUPS[V.tab].length; i++) counts.push(listFor(V.tab, i + 1, NOF).length);
const groupTotal = counts.length - 1;
const groupRows = SCENE.rail.visibleRows - 1;
const railX = SCENE.rail.x + SCENE.rail.rowPadX;
const railOf = (label, count, active) => ({
  sh: P,
  rail: { label: label + "   " + count, color: active ? "#FFFFFF" : P.inkDim, bg: active ? P.hot : P.line },
});
walk([{ ...SCENE.railRow, k: "text" }], railX, SCENE.rail.rowsY, railOf("ALL", counts[0], false), "rail");
for (let slot = 0; slot < groupRows; slot++) {
  const gi = slot;
  if (gi >= groupTotal) continue;
  walk([{ ...SCENE.railRow }], railX, SCENE.rail.rowsY + (slot + 1) * SCENE.rail.rowH, railOf(GROUPS[V.tab][gi], counts[gi + 1], V.group === gi), "rail");
}



// filter chips + search button (only when open)
const chips = V.tab === "sfx" ? SCENE.filterBarSpec.sfx : SCENE.filterBarSpec.vfx;
const chipAct = (key, val) => (val === "" ? "fa" : key === "dim" ? (val === "3d" ? "fd3" : "fd2") : key === "kind" ? (val === "loop" ? "fl" : "fo") : val === "world" ? "fw" : "fp");
for (let i = 0; i < chips.length; i++) {
  const c = chips[i];
  const a = chipAct(c.key, c.val);
  const on = a === "fa" ? (V.dim === "" && V.kind === "" && V.vfx === "") : a === "fd3" ? V.dim === "3d" : a === "fd2" ? V.dim === "2d" : a === "fl" ? V.kind === "loop" : a === "fo" ? V.kind === "oneshot" : a === "fw" ? V.vfx === "world" : V.vfx === "screen";
  add({ k: "textbutton", x: SCENE.filterBarSpec.chipX + i * (SCENE.filterBarSpec.chipW + SCENE.filterBarSpec.gap), y: SCENE.filterBarSpec.chipY, w: SCENE.filterBarSpec.chipW, h: SCENE.filterBarSpec.chipH, fill: "Solid", bg: on ? P.blue : P.row, bgAlpha: 1, text: c.label, textSize: 13, textColor: on ? "#FFFFFF" : P.inkDim, align: "Center" }, 0, 0, { sh: P, f: { text: c.label, textColor: on ? "#FFFFFF" : P.inkDim, bg: on ? P.blue : P.row } }, "f");
}
add({ k: "textbutton", x: SCENE.filterBarSpec.searchX, y: SCENE.filterBarSpec.searchY, w: SCENE.filterBarSpec.searchW, h: SCENE.filterBarSpec.searchH, fill: "Solid", bg: V.searchOpen ? P.green : P.panel, bgAlpha: 1, text: V.searchOpen ? "KEYBOARD OPEN" : "SEARCH", textSize: 14, textColor: V.searchOpen ? "#FFFFFF" : P.ink, align: "Center" }, 0, 0, { sh: P, f: { text: V.searchOpen ? "KEYBOARD OPEN" : "SEARCH", textColor: V.searchOpen ? "#FFFFFF" : P.ink, bg: V.searchOpen ? P.green : P.panel } }, "f");

// rows (hidden while the keyboard overlay is up)
if (!V.searchOpen) {
  for (let i = 0; i < page.length; i++) {
    walk(SCENE.row, SCENE.grid.originX, SCENE.grid.originY + i * SCENE.grid.rowH, { sh: P, r: rowFields(page[i]) }, "r");
  }
}

// simulated keyboard
if (V.searchOpen) {
  const kb = SCENE.keyboard;
  add({ k: "container", x: kb.x, y: kb.y, w: kb.w, h: kb.h, fill: "Solid", bg: P.shell, bgAlpha: 1 }, 0, 0, { sh: P }, "f");
  add({ k: "text", x: kb.x + 16, y: kb.queryY, w: kb.w - 420, h: kb.queryH, text: V.query === "" ? (V.kbPage === 1 ? "tap a prefix, then refine on ABC" : "type to search") : V.query, textSize: 20, textColor: V.query === "" ? P.faint : P.ink, textAnchor: mod.UIAnchor.CenterLeft, align: "Left" }, 0, 0, { sh: P, f: { text: "", textColor: P.ink, bg: "#000000" } }, "f");
  add({ k: "text", x: kb.x + kb.w - 396, y: kb.queryY, w: 380, h: kb.queryH, text: shown + " of " + total + " MATCH", textSize: 14, textColor: P.muted, textAnchor: mod.UIAnchor.CenterRight, align: "Right" }, 0, 0, { sh: P, f: { text: "", textColor: P.muted, bg: "#000000" } }, "f");
  if (V.kbPage === 1) {
    const pg = kb.prefixGrid;
    const all = V.tab === "sfx" ? CATALOG.sfxPrefixes : CATALOG.vfxPrefixes;
    const n = Math.min(all.length, pg.max);
    for (let i = 0; i < n; i++) {
      const e = all[i];
      const col = i % pg.cols, row = Math.floor(i / pg.cols);
      if (row >= pg.rows) break;
      add({ k: "textbutton", x: pg.x0 + col * (pg.w + pg.gap), y: pg.rowY[row], w: pg.w, h: pg.h, fill: "Solid", bg: P.row, bgAlpha: 1, text: e.token, textSize: 12, textColor: P.ink, align: "Center" }, 0, 0, { sh: P, f: { text: e.token, textColor: P.ink, bg: P.row } }, "f");
    }
  } else {
    for (let r = 0; r < kb.rows.length; r++) {
      const chars = kb.rows[r];
      for (let i = 0; i < chars.length; i++) {
        add({ k: "textbutton", x: kb.x0 + i * (kb.keyW + kb.gap), y: kb.rowY[r], w: kb.keyW, h: kb.keyH, fill: "Solid", bg: P.row, bgAlpha: 1, text: chars[i], textSize: 20, textColor: P.ink, align: "Center" }, 0, 0, { sh: P, f: { text: chars[i], textColor: P.ink, bg: P.row } }, "f");
      }
    }
  }
  let bx = kb.x0;
  for (const b of kb.bottom) {
    const isDone = b.action === "done";
    const isPage = b.action === "page";
    const label = isPage ? (V.kbPage === 1 ? "ABC KEYS" : "PREFIXES") : b.label;
    const bg = isDone ? P.green : b.action === "clr" ? P.redDim : isPage ? P.violet : P.row;
    add({ k: "textbutton", x: bx, y: kb.bottomY, w: b.w, h: kb.bottomH, fill: "Solid", bg: bg, bgAlpha: 1, text: label, textSize: 17, textColor: isDone ? "#FFFFFF" : P.ink, align: "Center" }, 0, 0, { sh: P, f: { text: label, textColor: isDone ? "#FFFFFF" : P.ink, bg: bg } }, "f");
    bx += b.w + kb.gap;
  }
}
} // end if (V.open)

// Opt-in with ?notes=1. Off by default: this is dev scaffolding, not part of the HUD, and it sits directly under the panel where it reads as if it were.
if (new URLSearchParams(location.search).get("notes") === "1") {
  const notes = [
    "VIEW=" + view + "   (" + "sfx | vfx | snow | gas | grouped | selected | armed | closed | empty | search | filters | pfxSfx | pfxVfx | music | radio" + ")",
    "SFX " + CATALOG.sfx.total + " across " + CATALOG.sfx.categories.length + " groups   |   VFX " + CATALOG.vfx.total + " across " + CATALOG.vfx.categories.length + " groups + " + SCREEN_FX.length + " player-wide",
    "banned and filtered out of the catalog: " + BANNED.length + "   |   snow FX: " + CATALOG.vfx.entries.filter((e) => e.name.includes("Snow")).length,
    "",
    "FIDELITY GAPS (Portal cannot do these; nothing below is faked):",
    "  rounded corners   -> square (UIBgFill has no border-radius)",
    "  diagonal stripes  -> alternating vertical slivers (containers cannot rotate)",
    "  any texture/image -> duration bar + meter slivers; UIImageType is a fixed 8-icon enum, no upload",
    "  outer drop shadow -> OutlineThin inset border",
    "  clipboard         -> no API, so the enum name is a static reference",
    "  circular buttons  -> square, with base/hover/pressed/focused colour states",
    "  U+25B6 / U+25C6 / U+2630 may be missing from the BF Text font -> falls back to plain letters",
  ];
  const box = new UIContainer({ ...BASE, position: { x: 20, y: 740 }, size: { width: 1120, height: 40 }, bgColor: hexToVec(P.panel), bgAlpha: 0.92, bgFill: mod.UIBgFill.Solid });
  for (let i = 0; i < notes.length; i++) {
    new UIText({ ...BASE, parent: box, position: { x: 6, y: i * 3.6 }, size: { width: 1108, height: 4 }, message: notes[i], textSize: 2.6, textColor: hexToVec(i === 0 ? P.amber : P.faint), textAlpha: 1, textAnchor: mod.UIAnchor.CenterLeft, bgColor: hexToVec("#000000"), bgAlpha: 0, bgFill: mod.UIBgFill.None });
  }
}
